export type TranslationKeys = typeof RAW_TRANSLATIONS.en;

export const TRANSLATIONS: Record<Language, TranslationKeys> = new Proxy(RAW_TRANSLATIONS as any, {
  get: (target, prop: string) => {
    if (target[prop]) return target[prop];
    return target.en;
  }
});
